"""TRAIN input features from frozen predicted endpoints; no attribute labels read."""
from pathlib import Path
import time
import numpy as np
import torch
from weld_pipeline.server_boundary_event_provenance_selector import BoundaryEventProvenanceSelector
from weld_pipeline.server_fixed_fragment_queries import FixedQueries
from weld_pipeline.sjg_local_runtime_904 import read,write,digest
BASE=Path(__file__).resolve().parents[1]/'server_rebuild/expansion_v1';OUT=BASE/'predicted_endpoint_attribute_features_v1'
def main():
 OUT.mkdir(exist_ok=False);torch.set_num_threads(2);folder=BASE/'boundary_provenance_batch02_expanded8_v1';r=read(folder/'receipt.json');assert digest(folder/'model.pt')==r['model_sha256'];state=torch.load(folder/'model.pt',map_location='cpu',weights_only=False);model=BoundaryEventProvenanceSelector().eval();model.load_state_dict(state['state_dict']);keys=state['keys'];extra={v['key'] for v in read(BASE/'additional_batch02_protocol.json')['cases']};write(OUT/'protocol.json',dict(keys=keys,endpoint_model_sha256=r['model_sha256'],features='Frozen query128 + selected left event128 + right event128 + left/right normalized provenance12 each + signed query-to-left/query-to-right/carrier-length mm divided1000',columns=411,endpoint_positions='Actual frozen model argmax, no GT snaps',query_scope='Registered TRAIN positive-query rows; training sampling is supervised, feature values contain no target geometry/attributes or owner IDs',frozen_encoder=True,attribute_label_reads=0,fit_calls=0,DEV_reads=0))
 for key in keys:
  started=time.perf_counter();data=BASE/'exhaustive_carrier_supervision_v1/positive_query'/key;assert digest(data/'receipt.json')==r['bindings'][key]['query'];records=read(data/'records.json');predpath=folder/(key+'_training_event_predictions.npz');pred=np.load(predpath);rows=pred['query_rows'];chosen=pred['chosen_event_ids'];queryids=np.asarray([records[int(i)]['feature_rows'][0]//2*4+records[int(i)]['query_index'] for i in rows]);cache=BASE/('batch02_boundary_anchor_training_v1' if key in extra else 'sampled_boundary_anchor_training_v1')/key;assert digest(cache/'receipt.json')==r['bindings'][key]['events'];cr=read(cache/'receipt.json');assert digest(cache/'events.npz')==cr['events_sha256'];ev=np.load(cache/'events.npz');positions=ev['positions_mm'];featureids=ev['feature_indices'];offsets=ev['offsets'];pids=ev['profile_ids'];lengths=ev['profile_length_mm'];pvdir=BASE/('batch02_boundary_event_provenance_v1' if key in extra else 'boundary_event_provenance_v1')/key;pr=read(pvdir/'receipt.json');assert digest(pvdir/'receipt.json')==r['bindings'][key]['provenance'] and digest(pvdir/'features.npy')==pr['features_sha256'];provenance=np.load(pvdir/'features.npy');inp=FixedQueries(BASE/'frozen_features/legacy_runtime'/('source_'+key),key);assert inp.bindings==cr['input_bindings'];result=np.empty((len(rows),411),np.float32)
  with torch.no_grad():
   for begin in range(0,len(rows),1024):
    end=min(begin+1024,len(rows));qid=queryids[begin:end];x=inp.features(qid);eid=chosen[begin:end];profile_index=np.searchsorted(offsets,eid,side='right')-1;assert np.array_equal(pids[profile_index],np.repeat(inp.pid[qid//4,None],2,axis=1));length=lengths[profile_index];event_rows=featureids[eid];raw=np.asarray(inp.raw[np.stack((2*event_rows,2*event_rows+1),axis=-1)],np.float64);ef=np.concatenate((raw.mean(2),raw.min(2),raw.max(2),(positions[eid]/length)[...,None]),axis=2).astype(np.float32);qx=model.query(torch.from_numpy(np.clip((x-state['mean'])/state['std'],-20,20))).numpy();ex=model.event(torch.from_numpy(np.clip((ef-state['mean'])/state['std'],-20,20))).numpy();pv=np.clip((provenance[eid]-state['provenance_mean'])/state['provenance_std'],-20,20);delta=(positions[eid]-x[:,456,None]*length)/1000.;rel=np.column_stack((delta,length[:,0]/1000.));result[begin:end]=np.column_stack((qx,ex.reshape(-1,256),pv.reshape(-1,24),rel))
  assert np.isfinite(result).all();dest=OUT/key;dest.mkdir();np.save(dest/'features.npy',result);np.savez(dest/'index.npz',query_rows=rows,query_ids=queryids);write(dest/'receipt.json',dict(key=key,rows=len(rows),columns=411,features_sha256=digest(dest/'features.npy'),index_sha256=digest(dest/'index.npz'),prediction_sha256=digest(predpath),query_receipt_sha256=digest(data/'receipt.json'),event_receipt_sha256=digest(cache/'receipt.json'),provenance_receipt_sha256=digest(pvdir/'receipt.json'),model_sha256=r['model_sha256'],attribute_label_reads=0,GT_endpoint_values_used_in_features=False,DEV_reads=0,seconds=time.perf_counter()-started));inp.close();print('COMPLETE',key,len(rows),flush=True)
 write(OUT/'receipt.json',dict(status='EIGHT_TRAIN_PREDICTED_ENDPOINT_ATTRIBUTE_INPUTS_FROZEN',fit_calls=0,attribute_label_reads=0,DEV_reads=0))
if __name__=='__main__':main()
